- Uses a 32-byte AES-256 key sourced from environment variable `CACHE_AES256_KEY`.
- Generates a cryptographically secure random 12-byte nonce per encryption.
- Prepends nonce to the ciphertext blob returned by `Encrypt`.
- On `Decrypt`, parses nonce from the first 12 bytes, then performs AES-GCM decryption with authentication tag verification.
- Returns explicit errors on decryption failure (e.g., authentication failure or malformed input).
- Uses Go standard library `crypto/aes` and `crypto/cipher` with AES-GCM mode, supporting hardware acceleration via AES-NI.
- Minimal memory allocations and efficient buffer reuse where appropriate.
- Thread-safe usage assumed as no internal mutable state is held between calls.

---

### MockEncryptionProvider Code Snippet

```go
package encryption

import (
    "crypto/aes"
    "crypto/cipher"
    "crypto/rand"
    "errors"
    "io"
    "os"
)

const nonceSize = 12

type MockEncryptionProvider struct {
    gcm cipher.AEAD
}

func NewMockEncryptionProvider() (*MockEncryptionProvider, error) {
    key := os.Getenv("CACHE_AES256_KEY")
    if len(key) != 32 {
        return nil, errors.New("CACHE_AES256_KEY must be exactly 32 bytes")
    }
    block, err := aes.NewCipher([]byte(key))
    if err != nil {
        return nil, err
    }
    gcm, err := cipher.NewGCM(block)
    if err != nil {
        return nil, err
    }
    return &MockEncryptionProvider{gcm: gcm}, nil
}

func (m *MockEncryptionProvider) Encrypt(plaintext []byte) ([]byte, error) {
    nonce := make([]byte, nonceSize)
    if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
        return nil, err
    }
    ciphertext := m.gcm.Seal(nil, nonce, plaintext, nil)
    // Prepend nonce to ciphertext
    result := make([]byte, nonceSize+len(ciphertext))
    copy(result[:nonceSize], nonce)
    copy(result[nonceSize:], ciphertext)
    return result, nil
}

func (m *MockEncryptionProvider) Decrypt(ciphertext []byte) ([]byte, error) {
    if len(ciphertext) < nonceSize {
        return nil, errors.New("ciphertext too short")
    }
    nonce := ciphertext[:nonceSize]
    actualCiphertext := ciphertext[nonceSize:]
    plaintext, err := m.gcm.Open(nil, nonce, actualCiphertext, nil)
    if err != nil {
        return nil, err // Authentication failed or corrupted data
    }
    return plaintext, nil
}
```

---

